import os,re
# strip block comments and line comments, count 'sorry' tokens
tot={}
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    for f in fn:
        if not f.endswith('.lean'): continue
        p=os.path.join(dp,f)
        s=open(p,encoding='utf-8',errors='replace').read()
        s=re.sub(r'/-.*?-/', '', s, flags=re.S)
        s=re.sub(r'--[^\n]*', '', s)
        n=len(re.findall(r'\bsorry\b', s))
        if n: tot[p]=n
print("comment-stripped sorry sites:", sum(tot.values()))
for k,v in sorted(tot.items(), key=lambda x:-x[1]): print(f"  {v:3d}  {k}")
raw=0
for dp,dn,fn in os.walk('AlgebraicJacobian'):
    for f in fn:
        if f.endswith('.lean'):
            raw+=len(re.findall(r'\bsorry\b', open(os.path.join(dp,f),encoding='utf-8',errors='replace').read()))
print("raw grep sorry occurrences:", raw)
